IPLDLY	equ	$F148		; level 2 after this many clocks
TBL	equ	$40000		; 1 KB: the long word at offset k holds k
SCR	equ	$41000		; scratch long words the chains load and store
ntrap	equ	$E100
npass	equ	$E104
nirq	equ	$E108
rearm	equ	$E10C		; the handler re-arms the delay

