	dc.l	$E000		; above the code
	dc.l	start
	rept	24
	dc.l	unexp
	endr
	dc.l	h_irq2		; 26 level 2 autovector
	rept	5
	dc.l	unexp
	endr
	dc.l	h_trap0		; 32
	dc.l	h_trap1		; 33: the pass is done
	dc.l	h_trap2		; 34: failure, d7 the block
	rept	221
	dc.l	unexp
	endr

